# Public Reproduction

Run from this directory:

```bash
python reproduce.py
```

The script loads the structure in `fixtures/public/structure.json`,
exports it to a `.res` file (`outputs/exported.res`) using the source
under `source/`, and validates the produced file against the format
format contract:

1. **species_reference_validity** — every atom record in the produced
   file must reference, through the file's own SFAC species list, the
   element named in that record (all references resolvable);
2. **round_trip_structure** — reading the produced file back with the
   library's own reader must return the input structure.

The script writes `outputs/export_validation_report.json` and prints a
summary. The report records one of three statuses:

- `post_fix_success` (exit code 0): both checks pass. This is the only
  status with a zero exit code.
- `pre_fix_expected_failure` (exit code 1): the export runs but the
  produced file violates the format. The report lists the atom records
  whose references do not resolve.
- `runner_failure` (exit code 2): an import, fixture, or environment
  problem prevented the export from running. This is never a scientific
  result.

No network access or large data set is required; the workflow completes
in seconds, dominated by package import time. The public fixture is one
illustrative structure: the repair must hold for any valid structure, not
only for this one.
"""Public reproduction for the .res export workflow.

A structure is exported to the SHELX/AIRSS `.res` format for an external
crystallographic workflow. This script loads the structure from
`fixtures/public/structure.json`, writes a `.res` file using the source
under `source/`, and checks the produced file against the format
documentation in `paper.md`:

1. species_reference_validity — every atom record in the produced file
   must reference, through the file's own SFAC species list, the element
   named in that record (1-based references, all resolvable);
2. round_trip_structure — reading the produced file back with the
   library's own reader must return the input structure.

The script writes `outputs/export_validation_report.json`. Exit codes:
0 = post_fix_success, 1 = pre_fix_expected_failure, 2 = runner_failure.
"""

from __future__ import annotations

import json
import sys
import traceback
from pathlib import Path

TASK_DIR = Path(__file__).resolve().parent
SOURCE = TASK_DIR / "source"
FIXTURES = TASK_DIR / "fixtures" / "public"
OUTPUTS = TASK_DIR / "outputs"


def read_atom_records(res_text: str) -> tuple[list[str], list[tuple[str, int]]]:
    """Read the SFAC species list and the (label, reference) pairs of every
    atom record from a .res file, as text."""
    species: list[str] = []
    atoms: list[tuple[str, int]] = []
    in_sfac = False
    for raw_line in res_text.splitlines():
        line = raw_line.strip()
        if not in_sfac:
            if line.startswith("SFAC"):
                species = line.split()[1:]
                in_sfac = True
            continue
        if line == "END":
            break
        fields = line.split()
        atoms.append((fields[0], int(fields[1])))
    if not species or not atoms:
        raise ValueError("produced file has no complete SFAC block")
    return species, atoms


def validate_species_references(res_text: str) -> dict:
    """Check that each atom record's reference resolves, through the file's
    own SFAC species list, to the element named in that record."""
    species, atoms = read_atom_records(res_text)
    unresolved = []
    mismatched = []
    for label, reference in atoms:
        if not 1 <= reference <= len(species):
            unresolved.append((label, reference))
        elif species[reference - 1] != label:
            mismatched.append((label, reference, species[reference - 1]))
    return {
        "status": "pass" if not unresolved and not mismatched else "fail",
        "num_atom_records": len(atoms),
        "num_declared_species": len(species),
        "unresolved_references": unresolved[:10],
        "mismatched_references": mismatched[:10],
    }


def main() -> int:
    OUTPUTS.mkdir(exist_ok=True)
    report: dict = {"checks": {}, "details": {}}
    try:
        sys.path.insert(0, str(SOURCE))
        from monty.serialization import loadfn
        from pymatgen.io.res import ResProvider, ResWriter

        structure = loadfn(FIXTURES / "structure.json")
        res_text = ResWriter(structure).string
        (OUTPUTS / "exported.res").write_text(res_text, encoding="utf-8")

        report["checks"]["species_reference_validity"] = validate_species_references(res_text)

        recovered = ResProvider.from_str(res_text).structure
        round_trip_ok = (
            recovered.lattice == structure.lattice
            and [str(sp) for sp in recovered.species] == [str(sp) for sp in structure.species]
            and recovered.frac_coords.tolist() == structure.frac_coords.tolist()
        )
        report["checks"]["round_trip_structure"] = {
            "status": "pass" if round_trip_ok else "fail"
        }

        report["details"]["num_sites"] = len(structure)
        report["details"]["composition"] = str(structure.composition)

        ok = all(check["status"] == "pass" for check in report["checks"].values())
        report["status"] = "post_fix_success" if ok else "pre_fix_expected_failure"
        exit_code = 0 if ok else 1

        print(f"status: {report['status']}")
        for name, check in report["checks"].items():
            print(f"  {name}: {check['status']}")
        validity = report["checks"]["species_reference_validity"]
        if validity["status"] == "fail":
            print(f"  atom records: {validity['num_atom_records']}, "
                  f"declared species: {validity['num_declared_species']}")
            print(f"  unresolved references (label, reference): {validity['unresolved_references']}")
            if validity["mismatched_references"]:
                print(f"  mismatched references: {validity['mismatched_references']}")
    except Exception:
        report["status"] = "runner_failure"
        report["error"] = traceback.format_exc()
        exit_code = 2
        print("status: runner_failure")
        print(report["error"])

    report_path = OUTPUTS / "export_validation_report.json"
    report_path.write_text(json.dumps(report, indent=2) + "\n", encoding="utf-8")
    print(f"report written to {report_path}")
    return exit_code


if __name__ == "__main__":
    sys.exit(main())
"""
Provides parsing and read/write support for ShelX .res files as produced by the AIRSS code.

Converting from and back to pymatgen objects is expected to be reversible, i.e. you
should get the same Structure or ComputedStructureEntry back. On the other hand, converting
from and back to a string/file is not guaranteed to be reversible, i.e. a diff on the output
would not be empty. The difference should be limited to whitespace, float precision, and the
REM entries.
"""

from __future__ import annotations

import datetime
import re
from dataclasses import dataclass
from typing import TYPE_CHECKING, Any, Callable, Literal

from monty.io import zopen
from monty.json import MSONable

from pymatgen.core import Element, Lattice, PeriodicSite, Structure
from pymatgen.entries.computed_entries import ComputedStructureEntry
from pymatgen.io.core import ParseError

if TYPE_CHECKING:
    from collections.abc import Iterator
    from datetime import date
    from pathlib import Path

    from typing_extensions import Self

    from pymatgen.core.trajectory import Vector3D


@dataclass(frozen=True)
class AirssTITL:
    seed: str
    pressure: float
    volume: float
    energy: float
    integrated_spin_density: float
    integrated_absolute_spin_density: float
    spacegroup_label: str
    appearances: int

    def __str__(self) -> str:
        return (
            f"TITL {self.seed:s} {self.pressure:.2f} {self.volume:.4f} {self.energy:.5f} "
            f"{self.integrated_spin_density:f} {self.integrated_absolute_spin_density:f} ({self.spacegroup_label:s}) "
            f"n - {self.appearances}"
        )


@dataclass(frozen=True)
class ResCELL:
    unknown_field_1: float
    a: float
    b: float
    c: float
    alpha: float
    beta: float
    gamma: float

    def __str__(self) -> str:
        return (
            f"CELL {self.unknown_field_1:.5f} {self.a:.5f} {self.b:.5f} {self.c:.5f} "
            f"{self.alpha:.5f} {self.beta:.5f} {self.gamma:.5f}"
        )


@dataclass(frozen=True)
class Ion:
    specie: str
    specie_num: int
    pos: Vector3D
    occupancy: float
    spin: float | None

    def __str__(self) -> str:
        if self.spin is None:
            ion_fmt = "{:<7s}{:<2d} {:.8f} {:.8f} {:.8f} {:f}"
            return ion_fmt.format(self.specie, self.specie_num, *self.pos, self.occupancy)

        ion_fmt = "{:<7s}{:<2d} {:.8f} {:.8f} {:.8f} {:f} {:5.2f}"
        return ion_fmt.format(self.specie, self.specie_num, *self.pos, self.occupancy, self.spin)


@dataclass(frozen=True)
class ResSFAC:
    species: set[str]
    ions: list[Ion]

    def __str__(self) -> str:
        species = " ".join(f"{specie:<2s}" for specie in self.species)
        ions = "\n".join(map(str, self.ions))
        return f"SFAC {species}\n{ions}\nEND\n"


@dataclass(frozen=True)
class Res:
    """Representation for the data in a res file."""

    TITL: AirssTITL | None
    REMS: list[str]
    CELL: ResCELL
    SFAC: ResSFAC

    def __str__(self) -> str:
        lines = ["TITL" if self.TITL is None else str(self.TITL)]

        lines += (f"REM {rem}" for rem in self.REMS)

        lines += (str(self.CELL), "LATT -1", str(self.SFAC))

        return "\n".join(lines)


class ResParseError(ParseError):
    """This exception indicates a problem was encountered during parsing due to unexpected formatting."""


class ResError(ValueError):
    """
    This exception indicates a problem was encountered while trying to retrieve a value or
    perform an action that a provider for the res file does not support.
    """


class ResParser:
    """Parser for the ShelX res file."""

    def __init__(self):
        self.line: int = 0
        self.filename: str | None = None
        self.source: str = ""

    def _parse_titl(self, line: str) -> AirssTITL | None:
        """Parses the TITL entry. Checks for AIRSS values in the entry."""
        fields = line.split(maxsplit=6)
        if len(fields) >= 6:
            # this is probably an AIRSS res file
            seed, pressure, volume, energy, spin, abs_spin = fields[:6]
            spg, nap = "P1", "1"
            if len(fields) == 7:
                rest = fields[6]
                # just extract spacegroup and num appearances from the rest
                lp = rest.find("(")
                rp = rest.find(")")
                spg = rest[lp + 1 : rp]
                nmin = rest.find("n -")
                nap = rest[nmin + 4 :]
            return AirssTITL(
                seed, float(pressure), float(volume), float(energy), float(spin), float(abs_spin), spg, int(nap)
            )
        # there should at least be the first 6 fields if it's an AIRSS res file
        # if it doesn't have them, then just stop looking
        return None

    def _parse_cell(self, line: str) -> ResCELL:
        """Parses the CELL entry."""
        fields = line.split()
        if len(fields) != 7:
            raise ResParseError(f"Failed to parse CELL {line=}, expected 7 fields.")
        field_1, a, b, c, alpha, beta, gamma = map(float, fields)
        return ResCELL(field_1, a, b, c, alpha, beta, gamma)

    def _parse_ion(self, line: str) -> Ion:
        """Parses entries in the SFAC block."""
        fields = line.split()
        if len(fields) == 6:
            spin = None
        elif len(fields) == 7:
            spin = float(fields[-1])
        else:
            raise ResParseError(f"Failed to parse ion entry {line}, expected 6 or 7 fields.")
        specie = fields[0]
        specie_num = int(fields[1])
        x, y, z, occ = map(float, fields[2:6])
        return Ion(specie, specie_num, (x, y, z), occ, spin)

    def _parse_sfac(self, line: str, it: Iterator[str]) -> ResSFAC:
        """Parses the SFAC block."""
        species = set(line.split())
        ions = []
        try:
            while True:
                line = next(it)
                if line == "END":
                    break
                ions.append(self._parse_ion(line))
        except StopIteration:
            raise ResParseError("Encountered end of file before END tag at end of SFAC block.")
        return ResSFAC(species, ions)

    def _parse_txt(self) -> Res:
        """Parses the text of the file."""
        _REMS: list[str] = []
        _TITL: AirssTITL | None = None
        _CELL: ResCELL | None = None
        _SFAC: ResSFAC | None = None

        txt = self.source
        it = iter(txt.splitlines())
        try:
            while True:
                line = next(it)
                self.line += 1
                split = line.split(maxsplit=1)
                splits = len(split)
                if splits == 0:
                    continue
                if splits == 1:
                    first, rest = *split, ""
                else:
                    first, rest = split
                if first == "TITL":
                    _TITL = self._parse_titl(rest)
                elif first == "REM":
                    _REMS.append(rest)
                elif first == "CELL":
                    _CELL = self._parse_cell(rest)
                elif first == "LATT":
                    pass  # ignore
                elif first == "SFAC":
                    _SFAC = self._parse_sfac(rest, it)
                else:
                    raise Warning(f"Skipping {line=}, tag {first} not recognized.")
        except StopIteration:
            pass
        if _CELL is None or _SFAC is None:
            raise ResParseError("Did not encounter CELL or SFAC entry when parsing.")
        return Res(_TITL, _REMS, _CELL, _SFAC)

    @classmethod
    def _parse_str(cls, source: str) -> Res:
        """Parses the res file as a string."""
        self = cls()
        self.source = source
        return self._parse_txt()

    @classmethod
    def _parse_file(cls, filename: str | Path) -> Res:
        """Parses the res file as a file."""
        self = cls()
        with zopen(filename, mode="r") as file:
            self.source = file.read()
            return self._parse_txt()


class ResWriter:
    """This class provides a means to write a Structure or ComputedStructureEntry to a res file."""

    @classmethod
    def _cell_from_lattice(cls, lattice: Lattice) -> ResCELL:
        """Produce CELL entry from a pymatgen Lattice."""
        return ResCELL(1.0, lattice.a, lattice.b, lattice.c, lattice.alpha, lattice.beta, lattice.gamma)

    @classmethod
    def _ions_from_sites(cls, sites: list[PeriodicSite]) -> list[Ion]:
        """Produce a list of entries for a SFAC block from a list of pymatgen PeriodicSite."""
        ions: list[Ion] = []
        i = 0
        for site in sites:
            for specie, occ in site.species.items():
                i += 1
                x, y, z = map(float, site.frac_coords)
                spin = site.properties.get("magmom")
                spin = spin and float(spin)
                ions.append(Ion(specie, i, (x, y, z), occ, spin))
        return ions

    @classmethod
    def _sfac_from_sites(cls, sites: list[PeriodicSite]) -> ResSFAC:
        """Produce a SFAC block from a list of pymatgen PeriodicSite."""
        ions = cls._ions_from_sites(sites)
        species = {ion.specie for ion in ions}
        return ResSFAC(species, ions)

    @classmethod
    def _res_from_structure(cls, structure: Structure) -> Res:
        """Produce a res file structure from a pymatgen Structure."""
        return Res(None, [], cls._cell_from_lattice(structure.lattice), cls._sfac_from_sites(list(structure)))

    @classmethod
    def _res_from_entry(cls, entry: ComputedStructureEntry) -> Res:
        """Produce a res file structure from a pymatgen ComputedStructureEntry."""
        seed = entry.data.get("seed") or str(hash(entry))
        pres = float(entry.data.get("pressure", 0))
        isd = float(entry.data.get("isd", 0))
        iasd = float(entry.data.get("iasd", 0))
        spg, _ = entry.structure.get_space_group_info()
        rems = [str(x) for x in entry.data.get("rems", [])]
        return Res(
            AirssTITL(seed, pres, entry.structure.volume, entry.energy, isd, iasd, spg, 1),
            rems,
            cls._cell_from_lattice(entry.structure.lattice),
            cls._sfac_from_sites(list(entry.structure)),
        )

    def __init__(self, entry: Structure | ComputedStructureEntry):
        """This class can be constructed from either a pymatgen Structure or ComputedStructureEntry object."""
        func: Callable[[Structure], Res] | Callable[[ComputedStructureEntry], Res]
        func = self._res_from_structure
        if isinstance(entry, ComputedStructureEntry):
            func = self._res_from_entry
        self._res = func(entry)

    def __str__(self):
        return str(self._res)

    @property
    def string(self) -> str:
        """The contents of the res file."""
        return str(self)

    def write(self, filename: str) -> None:
        """Write the res data to a file."""
        with zopen(filename, mode="w") as file:
            file.write(str(self))


class ResProvider(MSONable):
    """Provides access to elements of the res file in the form of familiar pymatgen objects."""

    def __init__(self, res: Res) -> None:
        """The :func:`from_str` and :func:`from_file` methods should be used instead of constructing this directly."""
        self._res = res

    @classmethod
    def _site_spin(cls, spin: float | None) -> dict[str, float] | None:
        """Check and return a dict with the site spin. Return None if spin is None."""
        if spin is None:
            return None
        return {"magmom": spin}

    @classmethod
    def from_str(cls, string: str) -> Self:
        """Construct a Provider from a string."""
        return cls(ResParser._parse_str(string))

    @classmethod
    def from_file(cls, filename: str | Path) -> Self:
        """Construct a Provider from a file."""
        return cls(ResParser._parse_file(filename))

    @property
    def rems(self) -> list[str]:
        """The full list of REM entries contained within the res file."""
        return self._res.REMS.copy()

    @property
    def lattice(self) -> Lattice:
        """Construct a Lattice from the res file."""
        cell = self._res.CELL
        return Lattice.from_parameters(cell.a, cell.b, cell.c, cell.alpha, cell.beta, cell.gamma)

    @property
    def sites(self) -> list[PeriodicSite]:
        """Construct a list of PeriodicSites from the res file."""
        sfac_tag = self._res.SFAC
