        return tuple(sorted({cls._species_symbol(specie) for site in sites for specie in site.species}))

    @classmethod
    def _ions_from_sites(
        cls, sites: list[PeriodicSite], species: tuple[str, ...] | None = None
    ) -> list[Ion]:
        """Produce a list of entries for a SFAC block from a list of pymatgen PeriodicSite."""
        if species is None:
            species = cls._species_from_sites(sites)
        species_numbers = {specie: idx for idx, specie in enumerate(species, start=1)}
        ions: list[Ion] = []
        for site in sites:
            site_species = sorted(
                site.species.items(), key=lambda item: species_numbers[cls._species_symbol(item[0])]
            )
            for specie, occ in site_species:
                symbol = cls._species_symbol(specie)
                x, y, z = map(float, site.frac_coords)
                spin = site.properties.get("magmom")
                spin = None if spin is None else float(spin)
                ions.append(Ion(symbol, species_numbers[symbol], (x, y, z), float(occ), spin))
        return ions

    @classmethod
    def _sfac_from_sites(cls, sites: list[PeriodicSite]) -> ResSFAC:
        """Produce a SFAC block from a list of pymatgen PeriodicSite."""
        species = cls._species_from_sites(sites)
        return ResSFAC(species, cls._ions_from_sites(sites, species))

