                and ion.pos == ion_groups[-1][0].pos
                and ion.spin == ion_groups[-1][0].spin
                and sum(item.occupancy for item in ion_groups[-1]) + ion.occupancy <= 1 + 1e-8
            ):
                ion_groups[-1].append(ion)
            else:
                ion_groups.append([ion])

        for ions in ion_groups:
            species: dict[Element, float] = {}
            for ion in ions:
                symbol = sfac_tag.species[ion.specie_num - 1]
                symbol = symbol[:1].upper() + symbol[1:].lower()
                try:
                    element = Element(symbol)
                except ValueError:
                    raise ResParseError(f"Invalid element symbol {symbol!r} in SFAC entry.")
                species[element] = species.get(element, 0) + ion.occupancy

            sites.append(
                PeriodicSite(
                    species,
                    ions[0].pos,
                    self.lattice,
                    properties=self._site_spin(ions[0].spin),
                )
            )

        return sites

    @property
    def structure(self) -> Structure:
        """Construct a Structure from the res file."""
        return Structure.from_sites(self.sites)


class AirssProvider(ResProvider):
    """
    Provides access to the res file as does ResProvider. This class additionally provides
    access to fields in the TITL entry and various other fields found in the REM entries
    that AIRSS puts in the file. Values in the TITL entry that AIRSS could not get end up as 0.
    If the TITL entry is malformed, empty, or missing then attempting to construct this class
    from a res file will raise a ResError.

    While AIRSS supports a number of geometry and energy solvers, CASTEP is the default. As such,
from __future__ import annotations

import os
import subprocess
import sys
from pathlib import Path

from pymatgen.core import Lattice, Structure
from pymatgen.entries.computed_entries import ComputedStructureEntry
from pymatgen.io.res import ResProvider, ResWriter


def _sfac_and_atoms(res_text: str) -> tuple[list[str], list[tuple[str, int]]]:
    lines = iter(res_text.splitlines())
    for line in lines:
        if line.startswith("SFAC"):
            species = line.split()[1:]
            break
    else:
        raise AssertionError("No SFAC entry")

    atoms = []
    for line in lines:
        if line == "END":
            break
        fields = line.split()
        atoms.append((fields[0], int(fields[1])))
    return species, atoms


def test_writer_uses_sfac_species_numbers_deterministically():
    structure = Structure(
        Lattice.cubic(5),
        ["Sr", "Ti", "O", "O", "O", "Li", "Fe"],
        [
            [0, 0, 0],
            [0.5, 0.5, 0.5],
            [0.5, 0.5, 0],
            [0.5, 0, 0.5],
            [0, 0.5, 0.5],
            [0.2] * 3,
            [0.3] * 3,
        ],
    )

    first = ResWriter(structure).string
    assert ResWriter(structure).string == first

    species, atoms = _sfac_and_atoms(first)
    assert species == sorted(species)
    assert all(species[reference - 1] == label for label, reference in atoms)
    assert len({reference for _, reference in atoms}) == len(species)


def test_partial_occupancies_and_site_spins_round_trip():
    structure = Structure(
        Lattice.hexagonal(3, 5),
        [{"Fe": 0.25, "Mn": 0.75}, "O", {"Li": 0.4}],
        [[0, 0, 0], [1 / 3, 2 / 3, 0.25], [0.5, 0.5, 0.5]],
        site_properties={"magmom": [0.0, -1.25, 2.5]},
    )

    res_text = ResWriter(structure).string
    recovered = ResProvider.from_str(res_text).structure

    assert [site.species for site in recovered] == [site.species for site in structure]
    assert recovered.site_properties["magmom"] == [0.0, -1.25, 2.5]
    assert " 0.00" in res_text


def test_writer_uses_element_symbols_for_oxidized_species():
    structure = Structure(Lattice.cubic(3), ["Fe2+", "O2-"], [[0, 0, 0], [0.5] * 3])

    species, atoms = _sfac_and_atoms(ResWriter(structure).string)

    assert species == ["Fe", "O"]
    assert atoms == [("Fe", 1), ("O", 2)]


def test_reader_resolves_species_number_and_occupancy():
    res_text = """TITL
CELL 1.0 3 3 3 90 90 90
LATT -1
SFAC C O
O1 2 0 0 0 0.25 0.00
END
"""

    site = ResProvider.from_str(res_text).structure[0]

    assert str(site.species) == "O0.25"
    assert site.properties["magmom"] == 0.0


def test_computed_entry_fallback_seed_is_stable():
    script = """
from pymatgen.core import Lattice, Structure
from pymatgen.entries.computed_entries import ComputedStructureEntry
from pymatgen.io.res import ResWriter

structure = Structure(Lattice.cubic(3), ["Na", "Cl"], [[0, 0, 0], [0.5] * 3])
print(ResWriter(ComputedStructureEntry(structure, -1.5)).string)
"""
    source_root = str(Path(__file__).resolve().parents[2])
    outputs = []
    for seed in ("1", "2"):
        env = {**os.environ, "PYTHONHASHSEED": seed}
        env["PYTHONPATH"] = os.pathsep.join(filter(None, (source_root, env.get("PYTHONPATH"))))
        outputs.append(subprocess.check_output([sys.executable, "-c", script], env=env, text=True))

    assert outputs[0] == outputs[1]
